/**
 * Repository checks no linter covers, run by `bun run lint`:
 * - standard rule 14: no em dash, and no en dash used as a break with whitespace on both sides;
 * - every row of a Markdown table has as many cells as its header (`markdown-tables.ts`);
 * - an applied migration never changes: no file under `packages/db/migrations` that the base
 *   holds is modified or deleted;
 * - the Dockerfile builds with the Bun version `packageManager` in package.json names.
 */
import { tableProblems } from './markdown-tables';

const DASH = /\u2014|\s\u2013\s/;
// Generated by release tooling, not written by hand.
const SKIP = new Set(['CHANGELOG.md', 'bun.lock']);
const MIGRATIONS = 'packages/db/migrations';

const tracked = (await Bun.$`git ls-files -z`.text()).split('\0').filter(Boolean);
const problems: string[] = [];

for (const path of tracked) {
  // A tracked file deleted and not committed yet has nothing to read; the migration check sees it.
  if (SKIP.has(path) || !(await Bun.file(path).exists())) continue;
  const bytes = await Bun.file(path).bytes();
  // Binary files (images, fonts) hold a NUL byte; every other tracked file is text to check.
  if (bytes.includes(0)) continue;
  const lines = new TextDecoder().decode(bytes).split('\n');
  lines.forEach((line, index) => {
    if (DASH.test(line)) problems.push(`${path}:${index + 1}: em dash or spaced en dash (rule 14)`);
  });
  if (path.endsWith('.md')) problems.push(...tableProblems(path, lines));
}

/**
 * The commit to compare migrations with. CI checks out a pull request merged into its base, one
 * commit deep, so it fetches that commit's parents and takes the first, the base it was merged
 * on. A local clone compares with where the branch left `origin/main`. Anything else, a push to
 * `main` or a clone without `origin/main`, has no base and skips the check.
 */
const migrationBase = async (): Promise<string | null> => {
  const sha = process.env.GITHUB_SHA;
  if (process.env.GITHUB_EVENT_NAME === 'pull_request' && sha) {
    await Bun.$`git fetch --no-tags --quiet --depth=2 origin ${sha}`.quiet().nothrow();
    const parent = await Bun.$`git rev-parse --verify --quiet HEAD^1`.quiet().nothrow();
    return parent.exitCode === 0 ? parent.text().trim() : null;
  }
  const base = await Bun.$`git merge-base HEAD origin/main`.quiet().nothrow();
  return base.exitCode === 0 ? base.text().trim() : null;
};

const base = await migrationBase();
if (base) {
  // The working tree against the base, so an edit not committed yet counts too.
  const changed = await Bun.$`git diff --name-status --no-renames ${base} -- ${MIGRATIONS}`.text();
  for (const line of changed.split('\n').filter(Boolean)) {
    const [status, path] = line.split('\t');
    if (status !== 'A')
      problems.push(`${path}: an applied migration never changes; add a new numbered file instead`);
  }
} else {
  console.warn(`check-repo: no base commit to compare ${MIGRATIONS} with; that check is skipped`);
}

const manifest = (await Bun.file('package.json').json()) as { packageManager?: string };
const bun = manifest.packageManager?.replace(/^bun@/, '');
const dockerfile = await Bun.file('Dockerfile').text();
if (!bun || !dockerfile.includes(`ARG BUN_VERSION=${bun}\n`)) {
  problems.push(`Dockerfile: ARG BUN_VERSION must equal packageManager (bun@${bun ?? '?'})`);
}

for (const problem of problems) console.error(problem);
process.exitCode = problems.length ? 1 : 0;
